  for (var i = 0; i < n; i++) g.S(h.petal(x, y, rot + i * 360 / n, r0, R, w, shape), o.lv || 1);
  if (o.center !== false) g.S(h.circle(x, y, R * (o.center || .28)), o.lv || 1);
  if (o.ring) g.DS(h.circle(x, y, R * o.ring), o.ringLv || 3);
